WITH scoped AS (SELECT * FROM novel_source_item WHERE channel_app_id='00de5521-d075-4472-87eb-cc5d1732f4d0'::uuid AND deleted_at IS NULL),classified AS (SELECT s.id,s.status,s.source_locale,s.novel_id,EXISTS(SELECT 1 FROM promo_link p WHERE p.novel_source_item_id=s.id AND p.status='fetched' AND p.deleted_at IS NULL) AS claimed,EXISTS(SELECT 1 FROM side_effect_intent i WHERE i.status='manual_review_required' AND i.request_summary->>'novelSourceItemId'=s.id::text) AS manual_review FROM scoped s) SELECT json_build_object('readAt',clock_timestamp(),'sourceStatusCounts',(SELECT json_object_agg(status,n) FROM (SELECT status,count(*) n FROM scoped GROUP BY status) x),'unclaimedNonManualLinked',(SELECT count(*) FROM classified WHERE status='linked' AND novel_id IS NOT NULL AND NOT claimed AND NOT manual_review),'unclaimedNonManualLinkedEnglish',(SELECT count(*) FROM classified WHERE status='linked' AND novel_id IS NOT NULL AND source_locale='en' AND NOT claimed AND NOT manual_review),'unclaimedNonManualPending',(SELECT count(*) FROM classified WHERE status='pending' AND novel_id IS NULL AND NOT claimed AND NOT manual_review),'pendingPromoRows',(SELECT count(*) FROM promo_link WHERE channel_app_id='00de5521-d075-4472-87eb-cc5d1732f4d0'::uuid AND status='pending'),'manualReviewIntentBaseline',(SELECT count(*) FROM side_effect_intent WHERE channel_app_id='00de5521-d075-4472-87eb-cc5d1732f4d0'::uuid AND status='manual_review_required'));
